<?php
require_once __DIR__ . '/../../includes/auth.php';
require_once __DIR__ . '/../../config/database.php';

requireRole('admin');

if (session_status() === PHP_SESSION_NONE) {
    session_start();
}

// Redirect helper
function redirectUsers($message) {
    header('Location: ' . BASE_URL . '/admin/users/?message=' . urlencode($message));
    exit;
}

// Only accept POST requests
if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    redirectUsers('invalid_request');
}

// Validate CSRF token generated by generateCsrfToken()
$submittedToken = $_POST['csrf_token'] ?? '';
$sessionToken = $_SESSION['csrf_token'] ?? '';

if (
    !is_string($submittedToken) ||
    !is_string($sessionToken) ||
    $sessionToken === '' ||
    !hash_equals($sessionToken, $submittedToken)
) {
    redirectUsers('invalid_csrf');
}

// Confirm requested action
$action = $_POST['action'] ?? '';

if ($action !== 'delete') {
    redirectUsers('invalid_action');
}

// Validate user ID
$userId = filter_input(INPUT_POST, 'user_id', FILTER_VALIDATE_INT);

if (!$userId || $userId <= 0) {
    redirectUsers('invalid_id');
}

// Prevent deleting the currently logged-in administrator
$currentUserId = $_SESSION['user_id'] ?? null;

if ($currentUserId !== null && (int)$currentUserId === (int)$userId) {
    redirectUsers('cannot_delete_self');
}

try {

    $pdo->beginTransaction();

    // Check whether the user exists
    $stmt = $pdo->prepare("
        SELECT users.id, users.role_id, roles.role_name
        FROM users
        LEFT JOIN roles ON users.role_id = roles.id
        WHERE users.id = ?
        LIMIT 1
        FOR UPDATE
    ");

    $stmt->execute([$userId]);
    $user = $stmt->fetch(PDO::FETCH_ASSOC);

    if (!$user) {
        $pdo->rollBack();
        redirectUsers('user_not_found');
    }

    // Prevent deleting the last administrator account
    if (strtolower($user['role_name'] ?? '') === 'admin') {

        $stmt = $pdo->prepare("
            SELECT COUNT(*)
            FROM users
            INNER JOIN roles ON users.role_id = roles.id
            WHERE LOWER(roles.role_name) = 'admin'
        ");

        $stmt->execute();
        $adminCount = (int)$stmt->fetchColumn();

        if ($adminCount <= 1) {
            $pdo->rollBack();
            redirectUsers('cannot_delete_last_admin');
        }
    }

    // Delete the account
    $stmt = $pdo->prepare("
        DELETE FROM users
        WHERE id = ?
    ");

    $stmt->execute([$userId]);

    $pdo->commit();

    redirectUsers('user_deleted');

} catch (PDOException $e) {

    if ($pdo->inTransaction()) {
        $pdo->rollBack();
    }

    error_log('User deletion error: ' . $e->getMessage());

    redirectUsers('delete_error');
}
